421	/// Each `ToolCall` has a `ToolResult` with the same call id later, with no
422	/// `UserMessage` or `AssistantMessage` between them. Each `ToolResult` closes
423	/// one earlier open `ToolCall` with its call id. A call id can repeat only
424	/// after its earlier call has a result. A call after a result starts a new
425	/// round, so no call may wait for a result then.
426	///
427	/// A copy is in `crates/paigasus-helikon-runtime-tokio/tests/deferred.rs`.
428	/// Keep the two copies the same.
429	pub fn assert_tool_calls_paired(messages: &[Item]) {
430	    // The calls that wait for a result, in call order.
431	    let mut outstanding: Vec<&str> = Vec::new();
432	    // A result came after the last call: the next call starts a new round.
433	    let mut seen_result_since_call = false;
434	    for item in messages {
435	        match item {
436	            Item::ToolCall { call_id, .. } => {
437	                assert!(
438	                    !outstanding.contains(&call_id.as_str()),
439	                    "call {call_id} repeats while it waits for a result: {messages:?}"
440	                );
441	                assert!(
442	                    !(seen_result_since_call && !outstanding.is_empty()),
443	                    "call {call_id} starts a new round while {outstanding:?} wait for a result: {messages:?}"
444	                );
445	                seen_result_since_call = false;
446	                outstanding.push(call_id);
447	            }
448	            Item::ToolResult { call_id, .. } => {
449	                let Some(p) = outstanding.iter().position(|c| *c == call_id.as_str()) else {
450	                    panic!("result {call_id} has no open earlier call: {messages:?}");
451	                };
452	                // Each result closes one call.
453	                outstanding.remove(p);
454	                seen_result_since_call = true;
455	            }
456	            Item::UserMessage { .. } | Item::AssistantMessage { .. } => {
457	                assert!(
458	                    outstanding.is_empty(),
459	                    "tool calls {outstanding:?} are not paired: {messages:?}"
460	                );
461	            }
462	            _ => {}
463	        }
464	    }
465	    assert!(
466	        outstanding.is_empty(),
467	        "tool calls {outstanding:?} are not paired: {messages:?}"
468	    );
469	}
