22	/// A scripted [`Model`] that emits a pre-recorded sequence of
23	/// [`ModelEvent`]s per call to [`Model::invoke`]. Pop one script per
24	/// invocation; running out of scripts yields a `ModelError`.
25	pub struct MockModel {
26	    scripts: Mutex<VecDeque<Vec<ModelEvent>>>,
27	}
28	
29	impl MockModel {
30	    pub fn with_scripts(scripts: Vec<Vec<ModelEvent>>) -> Arc<Self> {
31	        Arc::new(Self {
32	            scripts: Mutex::new(VecDeque::from(scripts)),
33	        })
34	    }
35	}
36	
37	#[async_trait]
38	impl Model for MockModel {
39	    async fn invoke(
40	        &self,
41	        _request: ModelRequest,
42	        _cancel: CancellationToken,
43	    ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
44	        let script = self
45	            .scripts
46	            .lock()
47	            .unwrap()
48	            .pop_front()
49	            .ok_or_else(|| ModelError::Other(anyhow::anyhow!("no more scripted responses")))?;
50	        Ok(Box::pin(stream::iter(script.into_iter().map(Ok))))
51	    }
52	
53	    fn capabilities(&self) -> ModelCapabilities {
54	        ModelCapabilities::default()
55	    }
56	}
