242	/// Build a `TokenUsage` with `input_tokens == total_tokens == total` (the other
243	/// fields zero). Constructed via `default()` + field assignment because
244	/// `TokenUsage` is `#[non_exhaustive]` (no struct-literal construction off-crate).
245	pub fn usage_total(total: u64) -> TokenUsage {
246	    let mut u = TokenUsage::default();
247	    u.input_tokens = total;
248	    u.total_tokens = total;
249	    u
