75	/// Run a root agent that defers its call to `b`, and store the run in a new
76	/// session. Returns the session.
77	async fn deferred_session(b: Arc<MockTool>) -> Arc<MemorySession> {
78	    let session = Arc::new(MemorySession::new());
79	    let agent = LlmAgent::builder::<()>()
80	        .name("root")
81	        .shared_model(MockModel::with_scripts(vec![call_b_turn()]))
82	        .shared_tool(b as Arc<dyn Tool<()>>)
83	        .build();
84	    let ctx = session_ctx(&session).with_deferred_tool_calls(true);
85	    let mut recorder = SessionRecorder::new("root").with_deferral_slot(ctx.deferral_handle());
86	    let input = AgentInput::from_user_text("go");
87	    recorder.record_input(&input.messages);
88	    let events = run_events(&agent, ctx, input).await;
89	    assert!(
90	        matches!(events.last(), Some(AgentEvent::RunDeferred { .. })),
91	        "{events:?}"
92	    );
93	    for ev in &events {
94	        recorder.observe(ev);
95	    }
96	    session.append(&recorder.drain()).await.unwrap();
97	    session
98	}
