100	/// The resume input: the resolution of the one open deferral, then `"next"`.
101	async fn resume_input(
102	    session: &MemorySession,
103	    root: &str,
104	    resolution: ToolResolution,
105	) -> (AgentInput, ResumePlan) {
106	    let events = session.events(None).await.unwrap();
107	    let snapshot = session.snapshot().await.unwrap();
108	    let open = open_deferrals(&events);
109	    assert_eq!(open.len(), 1, "{open:?}");
110	    let input =
111	        AgentInput::from_user_text("next").with_resolution(open[0].deferral_id(), resolution);
112	    let plan = ResumePlan::from_events(&events, &snapshot, root, &input, 8).expect("valid resume");
113	    (input.with_resume_plan(plan.clone()), plan)
114	}
