127	fn tool_output_text(events: &[AgentEvent], call_id: &str) -> String {
128	    events
129	        .iter()
130	        .find_map(|e| match e {
131	            AgentEvent::ToolOutputItem {
132	                item:
133	                    Item::ToolResult {
134	                        call_id: id,
135	                        content,
136	                    },
137	            } if id == call_id => Some(text_of(content)),
138	            _ => None,
139	        })
140	        .unwrap_or_else(|| panic!("no ToolOutputItem for {call_id}: {events:?}"))
141	}
