143	/// A short label for each event.
144	fn kind(ev: &AgentEvent) -> String {
145	    match ev {
146	        AgentEvent::RunStarted { .. } => "RunStarted".to_owned(),
147	        AgentEvent::TurnStarted { turn } => format!("TurnStarted({turn})"),
148	        AgentEvent::ToolOutputItem {
149	            item: Item::ToolResult { call_id, .. },
150	        } => format!("ToolOutputItem({call_id})"),
151	        AgentEvent::PermissionDenied { tool, .. } => format!("PermissionDenied({tool})"),
152	        AgentEvent::GuardrailTriggered { .. } => "GuardrailTriggered".to_owned(),
153	        AgentEvent::RunCompleted { .. } => "RunCompleted".to_owned(),
154	        AgentEvent::RunFailed { error } => format!("RunFailed({error})"),
155	        _ => "other".to_owned(),
156	    }
157	}
158	
159	fn kinds(events: &[AgentEvent]) -> Vec<String> {
160	    events.iter().map(kind).collect()
