645	/// The synthetic cancel text of core 0.6.0. It must equal
646	/// `CANCELLED_TOOL_CALL_TEXT` in `session.rs`, or `project()` does not
647	/// rewrite it.
648	const CANCELLED: &str = "tool call did not complete (run cancelled/timed out)";
649	
650	/// A copy of `session` in the layout of core 0.6.0 (before SMA-810).
651	///
652	/// `session` must hold one handoff run in the current layout. This removes
653	/// each `ToolReturned` directly after a `HandoffOccurred` (the transfer
654	/// results of that handoff response) and appends a cancel result for each
655	/// removed one at the end of the run's events, in call order. The run's
656	/// events end with its `ToolDeferred` events, so the cancels come after
657	/// them, where the core 0.6.0 recorder put them.
658	async fn with_late_transfer_results(session: &Arc<MemorySession>) -> Arc<MemorySession> {
659	    let recorded = session.events(None).await.unwrap();
660	    let mut events = Vec::with_capacity(recorded.len());
661	    let mut late = Vec::new();
662	    let mut after_handoff = false;
663	    for ev in recorded {
664	        match &ev {
665	            SessionEvent::HandoffOccurred { .. } => {
666	                after_handoff = true;
667	                events.push(ev);
668	            }
669	            SessionEvent::ToolReturned {
670	                call_id, content, ..
671	            } if after_handoff => {
672	                let text = text_of(content);
673	                assert!(
674	                    text.starts_with("transferred to ")
675	                        || text.starts_with("transfer not performed"),
676	                    "{call_id} after a handoff is not a transfer result: {text}"
677	                );
678	                late.push(call_id.clone());
679	            }
680	            _ => {
681	                after_handoff = false;
682	                events.push(ev);
683	            }
684	        }
685	    }
686	    assert!(!late.is_empty(), "the log has no transfer result to move");
687	    events.extend(late.into_iter().map(|id| {
688	        SessionEvent::tool_returned(
689	            id,
690	            vec![ContentPart::Text {
691	                text: CANCELLED.to_owned(),
692	            }],
693	        )
694	    }));
695	    let legacy = Arc::new(MemorySession::new());
696	    legacy.append(&events).await.unwrap();
697	    legacy
698	}
