1602	                    "{call_id} after a handoff is not a transfer result: {text}"
1603	                );
1604	                late.push(call_id.clone());
1605	            }
1606	            _ => {
1607	                after_handoff = false;
1608	                events.push(ev);
1609	            }
1610	        }
1611	    }
1612	    assert!(!late.is_empty(), "the log has no transfer result to move");
1613	    events.extend(late.into_iter().map(|id| {
1614	        SessionEvent::tool_returned(
1615	            id,
1616	            vec![ContentPart::Text {
1617	                text: CANCELLED.to_owned(),
1618	            }],
1619	        )
1620	    }));
1621	    let legacy = Arc::new(MemorySession::new());
1622	    legacy.append(&events).await.unwrap();
1623	    legacy
1624	}
1625	
1626	/// Run `triage` again on `session` with a new input, and check its model
1627	/// request: the tool calls are paired, and the result directly after the
1628	/// transfer call `t1` is `transferred to budgeting`.
1629	async fn assert_second_run_sends_paired_history(session: Arc<MemorySession>) {
1630	    let root_model = RecordingModel::with_scripts(vec![text_turn("again")]);
1631	    let budgeting = pay_agent(
1632	        "budgeting",
1633	        RecordingModel::with_scripts(vec![]),
1634	        &PayTool::new(),
1635	    );
1636	    let triage = LlmAgent::builder::<()>()
1637	        .name("triage")
1638	        .shared_model(Arc::clone(&root_model))
1639	        .handoff(budgeting)
1640	        .build();
1641	    let result = run(&triage, ctx(session.clone(), false), user("more"))
1642	        .await
1643	        .expect("the second run succeeds");
1644	    assert_eq!(result.final_output, "again");
1645	
1646	    let requests = root_model.requests();
1647	    assert_eq!(requests.len(), 1);
1648	    let m = &requests[0].messages;
1649	    assert_tool_calls_paired(m);
1650	    let call = m
1651	        .iter()
1652	        .position(|i| matches!(i, Item::ToolCall { call_id, .. } if call_id == "t1"))
1653	        .unwrap_or_else(|| panic!("no transfer call: {m:?}"));
1654	    match m.get(call + 1) {
1655	        Some(Item::ToolResult { call_id, content }) if call_id == "t1" => {
1656	            assert_eq!(text_of(content), "transferred to budgeting");
1657	        }
1658	        other => panic!("the transfer result is not after its call: {other:?} in {m:?}"),
1659	    }
1660	    assert!(
1661	        matches!(m.last(), Some(Item::UserMessage { content }) if text_of(content) == "more"),
1662	        "{m:?}"
1663	    );
1664	}
