1668	    let session = completed_handoff_session().await;
1669	    assert_eq!(
1670	        labels(&session).await,
1671	        [
1672	            "user_message(hi)",
1673	            "tool_called(t1)",
1674	            "handoff(triage->budgeting)",
1675	            "tool_returned(t1, transferred to budgeting)",
1676	            "assistant_message",
1677	        ]
1678	    );
1679	    assert_second_run_sends_paired_history(session).await;
1680	}
