1683	async fn second_run_on_a_legacy_session_sends_paired_history() {
1684	    let session = with_late_transfer_results(&completed_handoff_session().await).await;
1685	    assert_eq!(
1686	        labels(&session).await,
1687	        [
1688	            "user_message(hi)".to_owned(),
1689	            "tool_called(t1)".to_owned(),
1690	            "handoff(triage->budgeting)".to_owned(),
1691	            "assistant_message".to_owned(),
1692	            format!("tool_returned(t1, {CANCELLED})"),
1693	        ]
1694	    );
