94	    async fn on_event(&self, ctx: &RunContext<Ctx>, event: &HookEvent) -> HookDecision {
95	        if matches!(event, HookEvent::OnRunComplete) {
96	            ctx.cancel().cancel();
97	            // Suspend until the cancel tears down the stream; the `Allow` below is
98	            // unreachable on this branch.
99	            std::future::pending::<()>().await;
100	        }
101	        HookDecision::Allow
102	    }
103	}
104	
105	/// Barrier-synced tool: N instances on a `Barrier::new(N)` deadlock unless
106	/// they run concurrently.
107	pub struct MockToolBarrier {
108	    name: String,
109	    description: String,
110	    schema: serde_json::Value,
111	    barrier: Arc<tokio::sync::Barrier>,
112	}
113	
114	impl MockToolBarrier {
115	    pub fn new(name: &str, barrier: Arc<tokio::sync::Barrier>) -> Arc<Self> {
116	        Arc::new(Self {
117	            name: name.into(),
118	            description: format!("barrier tool {name}"),
119	            schema: serde_json::json!({"type": "object"}),
120	            barrier,
121	        })
122	    }
123	}
124	
125	#[async_trait]
126	impl<Ctx> Tool<Ctx> for MockToolBarrier
127	where
128	    Ctx: Send + Sync + 'static,
129	{
130	    fn name(&self) -> &str {
131	        &self.name
132	    }
133	    fn description(&self) -> &str {
134	        &self.description
135	    }
136	    fn schema(&self) -> &serde_json::Value {
137	        &self.schema
138	    }
139	    async fn invoke(
140	        &self,
141	        _ctx: &ToolContext<Ctx>,
142	        _args: serde_json::Value,
143	    ) -> Result<ToolOutput, ToolError> {
144	        self.barrier.wait().await;
145	        Ok(ToolOutput::new(serde_json::json!({"ok": true})))
146	    }
147	}
148	
149	/// Session that counts `append` calls — lets tests assert `finalize` ran.
150	#[derive(Default)]
151	pub struct CountingSession {
152	    appends: AtomicUsize,
153	}
154	
155	impl CountingSession {
156	    pub fn new() -> Arc<Self> {
157	        Arc::new(Self::default())
158	    }
159	    pub fn append_count(&self) -> usize {
160	        self.appends.load(Ordering::SeqCst)
161	    }
162	}
163	
164	#[async_trait]
165	impl Session for CountingSession {
166	    async fn append(&self, _events: &[SessionEvent]) -> Result<(), SessionError> {
167	        self.appends.fetch_add(1, Ordering::SeqCst);
168	        Ok(())
169	    }
170	    async fn events(&self, _since: Option<SequenceId>) -> Result<Vec<SessionEvent>, SessionError> {
171	        Ok(Vec::new())
172	    }
173	    async fn snapshot(&self) -> Result<ConversationSnapshot, SessionError> {
174	        Ok(ConversationSnapshot::default())
175	    }
176	}
177	
178	/// No-op session.
179	pub struct NoopSession;
180	
181	#[async_trait]
182	impl Session for NoopSession {
183	    async fn append(&self, _events: &[SessionEvent]) -> Result<(), SessionError> {
184	        Ok(())
185	    }
186	    async fn events(&self, _since: Option<SequenceId>) -> Result<Vec<SessionEvent>, SessionError> {
187	        Ok(Vec::new())
188	    }
189	    async fn snapshot(&self) -> Result<ConversationSnapshot, SessionError> {
190	        Ok(ConversationSnapshot::default())
191	    }
192	}
193	
194	pub fn noop_run_context() -> RunContext<()> {
195	    RunContext::ephemeral(()).with_session(Arc::new(NoopSession))
196	}
197	
198	pub fn run_context_with_cancel(cancel: CancellationToken) -> RunContext<()> {
199	    RunContext::ephemeral(())
200	        .with_session(Arc::new(NoopSession))
201	        .with_cancel(cancel)
202	}
203	
204	pub fn run_context_with_cancel_and_hooks(
205	    cancel: CancellationToken,
206	    hooks: Vec<Arc<dyn Hook<()>>>,
207	) -> RunContext<()> {
208	    let mut registry = HookRegistry::new();
209	    for h in hooks {
210	        registry.push(h);
211	    }
212	    RunContext::ephemeral(())
213	        .with_session(Arc::new(NoopSession))
214	        .with_hooks(registry)
215	        .with_cancel(cancel)
216	}
217	
218	pub fn run_context_with_session(session: Arc<dyn Session>) -> RunContext<()> {
219	    RunContext::ephemeral(()).with_session(session)
220	}
221	
222	pub fn run_context_with_session_and_cancel(
223	    session: Arc<dyn Session>,
224	    cancel: CancellationToken,
225	) -> RunContext<()> {
226	    RunContext::ephemeral(())
227	        .with_session(session)
228	        .with_cancel(cancel)
229	}
230	
231	/// Build an `LlmAgent<(), M>` with the given model and tools.
232	pub fn text_agent<M: Model + 'static>(
233	    model: Arc<M>,
234	    tools: Vec<Arc<dyn Tool<()>>>,
235	) -> LlmAgent<(), M> {
236	    LlmAgent::<(), _> {
237	        name: "test".into(),
238	        description: "test agent".into(),
239	        instructions: Arc::new("") as Arc<dyn Instructions<()>>,
240	        model,
241	        tools,
242	        handoffs: Vec::new(),
243	        output_type: None,
244	        input_guardrails: Vec::new(),
245	        output_guardrails: Vec::new(),
246	        hooks: Vec::new(),
247	        model_settings: ModelSettings::new(),
248	        config: RunConfig::default(),
249	        _output: std::marker::PhantomData,
250	    }
251	}
