220	/// Distinct `<component>` segments of every `target: "paigasus::…"` literal in
221	/// one file's source.
222	///
223	/// This is the source half of the doc-sync guard in
224	/// `tests/workspace-lints/tests/tracing_target_docs.rs`: the components found
225	/// here must match the ones the mdBook documents. It reports **components
226	/// only** — the `::<subsystem>` leaf is explicitly free to change (SMA-557 D1),
227	/// so guarding it would redden CI on legitimate refactors.
228	///
229	/// Comments, char literals and text nested inside a string literal are invisible
230	/// to it, because it looks for `target:` in `mask_trivia`'s masked buffer and
231	/// reads the literal's contents back out of the original source.
232	///
233	/// Not macro-aware: it keys on a `target:` token followed by a `paigasus::`
234	/// literal, so a non-`tracing` field named `target` holding such a string would
235	/// be a false positive. Such sites **do** exist in this workspace —
236	/// `crates/paigasus-helikon-core/src/command_match.rs` builds a `Redirect {
237	/// target: "...".into() }` struct literal with no `tracing` macro anywhere
238	/// near it — but none of them happen to hold a `"paigasus::…"`-shaped string,
239	/// so `scan_targets` tolerates them only because a non-`paigasus::` literal
240	/// yields `None` from the `component_of` helper; a future site whose non-tracing
241	/// `target:` field happened to start with `"paigasus::"` would be a silent
242	/// false positive here. [`scan_invocations`] is immune to this class of bug
243	/// structurally, because it only classifies a `target:` argument found
244	/// while walking a *recognised macro invocation's* argument list.
245	///
246	/// A comment may sit between `target:` and its literal — `tracing` accepts
247	/// `target: /* note */ "paigasus::x::y"` — and that form is recognised. What is
248	/// **not** recognised is a target that is not a literal at all:
249	/// `target: SOME_CONST`, a `const &'static str`, which `tracing` also accepts,
250	/// yields no component. No such site exists in this workspace today.
251	pub fn scan_targets(src: &str) -> BTreeSet<String> {
252	    const NEEDLE: &[u8] = b"target:";
253	    let masked = mask_trivia(src);
254	    let b = &masked.buf[..];
255	    let mut out = BTreeSet::new();
256	    let mut i = 0;
257	    while let Some(rel) = find_sub(&b[i..], NEEDLE) {
258	        let after = i + rel + NEEDLE.len();
259	        // Take the next literal whose span is separated from `target:` by
260	        // nothing but whitespace *in the masked buffer*. That test is what
261	        // makes a comment in the gap transparent: `mask_trivia` blanks
262	        // comments to spaces, so they read as whitespace here, while any real
263	        // token — an identifier, a `format!`, an opening paren — does not, and
264	        // correctly rejects the match. Testing the raw source instead would
265	        // stop at the comment's leading `/` and silently skip the site.
266	        if let Some(&(start, end)) = masked.string_literals.iter().find(|&&(start, _)| {
267	            start >= after && b[after..start].iter().all(u8::is_ascii_whitespace)
268	        }) {
269	            if let Some(component) = component_of(&src[start..end]) {
270	                out.insert(component);
271	            }
272	        }
273	        i = after;
274	    }
275	    out
276	}
