278	/// The `<component>` of a `"paigasus::<component>::…"` string literal, given the
279	/// literal's raw text **including** its delimiters.
280	///
281	/// Returns `None` for a literal outside the namespace, or one whose component
282	/// segment is empty (`"paigasus::"`).
283	fn component_of(literal: &str) -> Option<String> {
284	    let content = literal_content(literal)?;
285	    let rest = content.strip_prefix("paigasus::")?;
286	    let component = match rest.find("::") {
287	        Some(k) => &rest[..k],
288	        None => rest,
289	    };
290	    if component.is_empty() {
291	        None
292	    } else {
293	        Some(component.to_owned())
294	    }
295	}
