314	/// Index of the first occurrence of `needle` in `haystack`, or `None`.
315	///
316	/// `std` has no substring search for `&[u8]`, and this crate takes no
317	/// dependencies.
318	fn find_sub(haystack: &[u8], needle: &[u8]) -> Option<usize> {
319	    if needle.is_empty() || haystack.len() < needle.len() {
320	        return None;
321	    }
322	    haystack.windows(needle.len()).position(|w| w == needle)
323	}
324	
325	fn is_ident_byte(c: u8) -> bool {
326	    c.is_ascii_alphanumeric() || c == b'_'
327	}
328	
329	/// Start/end (exclusive) of the identifier immediately preceding `at`, if
330	/// any, skipping any whitespace between the identifier and `at` (so
331	/// `warn ! (` still finds `warn`). Stops at `:`, so a qualified
332	/// `tracing::warn!` yields just the `warn` range.
333	fn ident_range_before(b: &[u8], at: usize) -> Option<(usize, usize)> {
334	    let mut e = at;
335	    while e > 0 && b[e - 1].is_ascii_whitespace() {
336	        e -= 1;
337	    }
338	    let mut s = e;
339	    while s > 0 && is_ident_byte(b[s - 1]) {
340	        s -= 1;
341	    }
342	    if s == e {
343	        return None;
344	    }
345	    Some((s, e))
346	}
