348	/// Line numbers (1-based) in `src` that carry a `// allow(<marker>)`-shaped
349	/// opt-out comment — [`ALLOW_MARKER`] or [`ALLOW_MARKER_COVERAGE`] — either
350	/// as a standalone comment or trailing code.
351	///
352	/// Matched against the *raw* source, because the marker text lives inside a
353	/// comment and [`mask_trivia`] has already blanked comments to spaces by the
354	/// time this runs. But raw-text matching alone cannot tell a genuine `//`
355	/// comment from marker-shaped text that merely appears inside a string, a
356	/// raw string, or a block comment — so an occurrence only counts when its
357	/// byte range falls inside `line_comment_ranges`, the genuine line-comment
358	/// spans [`mask_trivia`] already identified while masking. Re-deriving those
359	/// boundaries independently here, instead of reusing them, would risk a
360	/// second lexer disagreeing with the first about what counts as a comment.
361	fn collect_allow_marker_lines(
362	    src: &str,
363	    line_comment_ranges: &[(usize, usize)],
364	    marker: &str,
365	) -> BTreeSet<usize> {
366	    let bytes = src.as_bytes();
367	    src.match_indices(marker)
368	        .filter(|&(pos, _)| {
369	            let end = pos + marker.len();
370	            line_comment_ranges
371	                .iter()
372	                .any(|&(start, stop)| pos >= start && end <= stop)
373	        })
374	        .map(|(pos, _)| line_of(bytes, pos))
375	        .collect()
376	}
