662	fn starts_with_ident(b: &[u8], at: usize, word: &str) -> bool {
663	    let w = word.as_bytes();
664	    b.len() >= at + w.len()
665	        && &b[at..at + w.len()] == w
666	        && !b.get(at + w.len()).is_some_and(|&c| is_ident_byte(c))
667	}
668	
669	fn line_of(b: &[u8], at: usize) -> usize {
670	    b[..at].iter().filter(|&&c| c == b'\n').count() + 1
671	}
672	
673	/// Walk one macro invocation's top-level (depth 0) arguments and call `f`
674	/// with the byte offset each argument starts at (its first non-whitespace
675	/// byte). `open` is the index of the invocation's opening delimiter (`(`,
676	/// `[` or `{`) and `closer` its matching close byte, so a `{`- or
677	/// `[`-delimited invocation terminates on its own closer rather than on the
678	/// first `)` it happens to contain.
679	///
680	/// Shared by [`collect_args`] (which flags an argument opening with
681	/// `target =` / `parent =`) and [`classify_target_arg`] (which classifies an
682	/// argument opening with `target:`), so the depth-tracking, comma-splitting
683	/// walk that decides what counts as "top-level" lives in exactly one place —
684	/// the two callers would otherwise have to agree on it independently.
685	fn for_each_top_level_arg(
686	    b: &[u8],
687	    open: usize,
688	    closer: u8,
689	    mut f: impl FnMut(usize),
690	) -> Result<(), MismatchedDelimiter> {
691	    let mut k = open + 1;
692	    let mut depth = 0usize;
693	    let mut at_arg_start = true;
694	    while k < b.len() {
695	        let c = b[k];
696	        if c == b'(' || c == b'[' || c == b'{' {
697	            depth += 1;
698	            at_arg_start = false;
699	        } else if c == b')' || c == b']' || c == b'}' {
700	            if depth == 0 {
701	                // Well-formed Rust nests delimiters strictly (each close
702	                // matches the most recently opened group), so the closer
703	                // reached at depth 0 must be this invocation's own —
704	                // any interior groups, of any delimiter kind, were already
705	                // closed by the depth count above. A mismatch here means a
706	                // future `mask_trivia` desync, not valid Rust; return it
707	                // rather than panic so a multi-file caller can name the file.
708	                if c != closer {
709	                    return Err(MismatchedDelimiter {
710	                        byte: k,
711	                        found: c,
712	                        expected: closer,
713	                    });
714	                }
715	                return Ok(());
716	            }
717	            depth -= 1;
718	            at_arg_start = false;
719	        } else if c == b',' && depth == 0 {
720	            at_arg_start = true;
721	        } else if c.is_ascii_whitespace() {
722	            // Whitespace never ends an argument-start position.
723	        } else {
724	            if at_arg_start && depth == 0 {
725	                f(k);
726	            }
727	            at_arg_start = false;
728	        }
729	        k += 1;
730	    }
731	    Ok(())
732	}
733	
734	/// Flag any top-level argument that opens with `target =` or `parent =`.
735	fn collect_args(
736	    b: &[u8],
737	    open: usize,
738	    closer: u8,
739	    macro_name: &str,
740	    out: &mut Vec<Offense>,
741	) -> Result<(), MismatchedDelimiter> {
742	    for_each_top_level_arg(b, open, closer, |k| {
743	        if let Some(kw) = KEYWORDS.iter().find(|kw| starts_with_ident(b, k, kw)) {
744	            let mut m = k + kw.len();
745	            while m < b.len() && b[m].is_ascii_whitespace() {
746	                m += 1;
747	            }
748	            if b.get(m) == Some(&b'=') && b.get(m + 1) != Some(&b'=') {
749	                out.push(Offense {
750	                    line: line_of(b, k),
751	                    macro_name: macro_name.to_owned(),
752	                    keyword: (*kw).to_owned(),
753	                });
754	            }
755	        }
756	    })
757	}
