1	//! Workspace-wide source lints for the Helikon repo.
2	//!
3	//! Internal, never published. See
4	//! `docs/superpowers/specs/2026-08-19-sma-543-tracing-target-design.md`.
5	
6	use std::collections::BTreeSet;
7	
8	/// One `target =` / `parent =` argument found inside a `tracing` macro.
9	#[derive(Debug, Clone, PartialEq, Eq)]
10	pub struct Offense {
11	    /// 1-based line number of the offending keyword.
12	    pub line: usize,
13	    /// Macro it appeared in, unqualified (e.g. `warn` for `tracing::warn!`).
14	    pub macro_name: String,
15	    /// Which keyword was misused: `target` or `parent`.
16	    pub keyword: String,
17	}
18	
19	/// Macros where `target:` / `parent:` are macro syntax, not field names.
20	const TRACING_MACROS: &[&str] = &[
21	    "trace",
22	    "debug",
23	    "info",
24	    "warn",
25	    "error",
26	    "event",
27	    "span",
28	    "trace_span",
29	    "debug_span",
30	    "info_span",
31	    "warn_span",
32	    "error_span",
33	    // Predicate macros — not used anywhere in this workspace today, but they
34	    // also accept `target:` and are included here for completeness.
35	    "enabled",
36	    "event_enabled",
37	    "span_enabled",
38	];
39	
40	/// Keywords that must be introduced with `:` and never with `=`.
41	const KEYWORDS: &[&str] = &["target", "parent"];
42	
43	/// Opt-out marker for a call site where `target`/`parent` are legitimate
44	/// field names, not the macro's target/parent syntax — e.g.
45	/// `tracing::info!(target: "paigasus::http", target = %uri, "req")`, where
46	/// the second `target` is an ordinary field. Written as a `// allow(...)`
47	/// comment either on the line immediately before the macro invocation, or
48	/// trailing the invocation's own line.
49	const ALLOW_MARKER: &str = "// allow(tracing-target-syntax)";
50	
51	/// Opt-out marker for a call site that is deliberately exempt from the
52	/// `target:` coverage requirement Task 9 enforces — e.g. a legitimate
53	/// untargeted or computed-target invocation that cannot be made a literal.
54	/// Same placement rules as the syntax lint's own marker: a `// allow(...)`
55	/// comment either immediately before the invocation or trailing its own line.
56	pub const ALLOW_MARKER_COVERAGE: &str = "// allow(tracing-target-coverage)";
57	
58	/// An interior delimiter did not close the way the argument walker expected
59	/// while walking a macro invocation's argument list. Well-formed Rust nests
60	/// delimiters strictly, so this should be unreachable against real source —
61	/// it exists to catch a future desync between the trivia masker and the
62	/// walker's depth tracking, surfaced as a value a caller can
63	/// attribute to the file it was reading rather than a `debug_assert_eq!`
64	/// panic naming only a byte offset (second SMA-543 review wave).
65	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
66	pub struct MismatchedDelimiter {
67	    /// Byte offset into the masked source where the mismatch was found.
68	    pub byte: usize,
69	    /// The closing byte actually encountered.
70	    pub found: u8,
71	    /// The closing byte the invocation's own opening delimiter required.
72	    pub expected: u8,
73	}
74	
75	impl std::fmt::Display for MismatchedDelimiter {
76	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
77	        write!(
78	            f,
79	            "mismatched delimiter ending macro invocation at byte {}: found {:?}, expected {:?}",
80	            self.byte, self.found as char, self.expected as char
81	        )
82	    }
83	}
84	
85	impl std::error::Error for MismatchedDelimiter {}
86	
87	/// Scan Rust source for `tracing` macro arguments written `target = …` or
88	/// `parent = …`, which the macros silently treat as ordinary fields.
89	///
90	/// Every top-level argument is inspected, not just the first: for the span and
91	/// event macros the correct syntax puts `target:` *before* the level or span
92	/// name, so the erroneous form is only reachable in a later position.
93	///
94	/// A macro invocation is recognised by its **final path segment** alone —
95	/// `tracing::warn!`, `crate::obs::warn!`, `self::warn!`, a bare `warn!`
96	/// reached via `use tracing::warn;`, and a bare alias reached via
97	/// `use tracing::warn as w;` are all matched — because a qualifier (or an
98	/// entire import path) can be renamed or re-exported and still reach the
99	/// exact same macro; requiring the qualifier to read literally `tracing`
100	/// produced false negatives (second review wave). The accepted cost (spec
101	/// §4.7) is that an unrelated macro whose final segment merely collides
102	/// with a tracing macro name, e.g. `mycrate::warn!(target = "x", "m")`, is
103	/// now flagged too — silence a genuine collision with the
104	/// `// allow(tracing-target-syntax)` escape hatch below.
105	///
106	/// `target`/`parent` are also legal field names in ordinary code. A call
107	/// site may opt out of detection with a `// allow(tracing-target-syntax)`
108	/// comment, either on the line immediately before the invocation or
109	/// trailing the invocation's own line — e.g.
110	/// `tracing::info!(target: "ns", target = %uri, "m"); // allow(tracing-target-syntax)`.
111	///
112	/// Comments and literals are blanked before scanning, so a macro written out
113	/// inside a comment, doc example or string is never flagged.
114	///
115	/// # Panics
116	///
117	/// Panics, without file context, if the source contains a delimiter
118	/// mismatch that should be unreachable against valid Rust — see [`try_scan`]
119	/// for a form that surfaces this diagnosably instead.
120	pub fn scan(src: &str) -> Vec<Offense> {
121	    try_scan(src).unwrap_or_else(|e| panic!("{e}"))
122	}
123	
124	/// Fallible form of [`scan`]. Returns [`MismatchedDelimiter`] instead of
125	/// panicking, so a caller walking many files (see
126	/// `tests/workspace-lints/tests/tracing_target_syntax.rs`) can attribute the
127	/// failure to the file it was reading — something a panic raised from
128	/// inside this `&str`-only function cannot do on its own.
129	pub fn try_scan(src: &str) -> Result<Vec<Offense>, MismatchedDelimiter> {
130	    let masked = mask_trivia(src);
131	    let allow_lines = collect_allow_marker_lines(src, &masked.line_comments, ALLOW_MARKER);
132	    let b = &masked.buf[..];
133	    let aliases = collect_macro_aliases(b);
134	    let mut offenses = Vec::new();
135	    walk_invocations(b, &aliases, |inv| {
136	        let macro_line = line_of(b, inv.name_start);
137	        // The marker suppresses the whole invocation, so this checks the
138	        // invocation's own start line, not each offending keyword's line
139	        // (an invocation can span many lines).
140	        let suppressed = allow_lines.contains(&macro_line)
141	            || (macro_line > 1 && allow_lines.contains(&(macro_line - 1)));
142	        if !suppressed {
143	            collect_args(b, inv.open, inv.closer, inv.name, &mut offenses)?;
144	        }
145	        Ok(())
146	    })?;
147	    Ok(offenses)
148	}
149	
150	/// One recognised `tracing`-macro invocation's location, as found by
151	/// [`walk_invocations`]: `name` is the macro's final path segment,
152	/// `name_start` the byte offset that segment begins at (used for line
153	/// reporting), and `open`/`closer` locate its argument list the way
154	/// [`for_each_top_level_arg`] expects.
155	struct MacroInvocation<'a> {
156	    name: &'a str,
157	    name_start: usize,
158	    open: usize,
159	    closer: u8,
160	}
161	
162	/// Find every recognised `tracing`-macro invocation in the masked buffer `b`
163	/// and call `f` with its location. Shared by [`try_scan`] (which flags
164	/// `target =` / `parent =` syntax offenses inside each invocation) and
165	/// [`scan_invocations`] (which classifies each invocation's `target:`
166	/// argument), so the "find `ident !` followed by an opening delimiter, then
167	/// recognise the identifier as a tracing macro" walk lives in exactly one
168	/// place. `f` may fail with [`MismatchedDelimiter`] while walking the
169	/// invocation's own argument list; that error is propagated immediately.
170	fn walk_invocations<'a>(
171	    b: &'a [u8],
172	    aliases: &[String],
173	    mut f: impl FnMut(MacroInvocation<'a>) -> Result<(), MismatchedDelimiter>,
174	) -> Result<(), MismatchedDelimiter> {
175	    let mut i = 0;
176	    while i < b.len() {
177	        if b[i] != b'!' {
178	            i += 1;
179	            continue;
180	        }
181	        let Some((name_start, name_end)) = ident_range_before(b, i) else {
182	            i += 1;
183	            continue;
184	        };
185	        let Ok(name) = std::str::from_utf8(&b[name_start..name_end]) else {
186	            i += 1;
187	            continue;
188	        };
189	        let mut j = i + 1;
190	        while j < b.len() && b[j].is_ascii_whitespace() {
191	            j += 1;
192	        }
193	        // Macros accept all three delimiters with identical token trees —
194	        // `warn!(...)`, `warn![...]` and `warn!{...}` are equally valid Rust
195	        // and equally reproduce the SMA-543 defect, so all three must be
196	        // recognised as an invocation, not just `(`.
197	        let closer = match b.get(j) {
198	            Some(b'(') => b')',
199	            Some(b'[') => b']',
200	            Some(b'{') => b'}',
201	            _ => {
202	                i += 1;
203	                continue;
204	            }
205	        };
206	        let is_tracing_macro = TRACING_MACROS.contains(&name) || aliases.iter().any(|a| a == name);
207	        if is_tracing_macro {
208	            f(MacroInvocation {
209	                name,
210	                name_start,
211	                open: j,
212	                closer,
213	            })?;
214	        }
215	        i = j + 1;
216	    }
217	    Ok(())
218	}
