297	/// The content of a string literal, given its raw text **including** its
298	/// delimiters and any `r#…#`/`b`/`c` prefix — i.e. the text strictly between
299	/// the first and last `"` byte. Shared by [`component_of`] (which further
300	/// requires a `paigasus::` prefix) and [`classify_target_arg`] (which does
301	/// not).
302	///
303	/// Returns `None` if `literal` contains no `"` pair at all, which should not
304	/// happen for a span taken from [`Masked::string_literals`].
305	fn literal_content(literal: &str) -> Option<&str> {
306	    let open = literal.find('"')?;
307	    let close = literal.rfind('"')?;
308	    if close <= open {
309	        return None;
310	    }
311	    literal.get(open + 1..close)
312	}
