314	/// Index of the first occurrence of `needle` in `haystack`, or `None`.
315	///
316	/// `std` has no substring search for `&[u8]`, and this crate takes no
317	/// dependencies.
318	fn find_sub(haystack: &[u8], needle: &[u8]) -> Option<usize> {
319	    if needle.is_empty() || haystack.len() < needle.len() {
320	        return None;
321	    }
322	    haystack.windows(needle.len()).position(|w| w == needle)
323	}
