378	/// Public form of the internal allow-marker search for a caller (Task 8's
379	/// integration test, Task 9's coverage lint) that only has `src` and does not
380	/// already hold the masker's line-comment ranges — it re-derives them itself
381	/// from `src` to get the line-comment ranges the search needs.
382	///
383	/// `marker` is any `// allow(...)`-shaped opt-out text, typically the syntax
384	/// lint's own marker or [`ALLOW_MARKER_COVERAGE`].
385	pub fn allow_marker_lines(src: &str, marker: &str) -> BTreeSet<usize> {
386	    let masked = mask_trivia(src);
387	    collect_allow_marker_lines(src, &masked.line_comments, marker)
388	}
