390	/// Local names that resolve to a `tracing` macro via
391	/// `use <path>::<macro> as <alias>;` (or the grouped form
392	/// `use <path>::{<macro> as <alias>, ...};`), so a fully renamed bare call
393	/// like `w!(target = "x", "m")` is still matched by its resolved identity.
394	/// Operates on the masked buffer, so an alias mentioned only inside a
395	/// comment or string is ignored.
396	///
397	/// A candidate word is only treated as an import alias when it sits
398	/// immediately after `::`, `{` or `,` (modulo whitespace) and immediately
399	/// before `as <ident>` (also modulo whitespace) — so an unrelated cast
400	/// expression whose operand happens to be named e.g. `warn` is not mistaken
401	/// for one.
402	fn collect_macro_aliases(b: &[u8]) -> Vec<String> {
403	    let mut aliases = Vec::new();
404	    let mut i = 0;
405	    while i < b.len() {
406	        if !is_ident_byte(b[i]) {
407	            i += 1;
408	            continue;
409	        }
410	        let start = i;
411	        while i < b.len() && is_ident_byte(b[i]) {
412	            i += 1;
413	        }
414	        let end = i;
415	        let Ok(word) = std::str::from_utf8(&b[start..end]) else {
416	            continue;
417	        };
418	        if !TRACING_MACROS.contains(&word) {
419	            continue;
420	        }
421	        let mut p = start;
422	        while p > 0 && b[p - 1].is_ascii_whitespace() {
423	            p -= 1;
424	        }
425	        let in_import_position =
426	            (p >= 2 && &b[p - 2..p] == b"::") || (p >= 1 && matches!(b[p - 1], b'{' | b','));
427	        if !in_import_position {
428	            continue;
429	        }
430	        let mut m = end;
431	        while m < b.len() && b[m].is_ascii_whitespace() {
432	            m += 1;
433	        }
434	        if !starts_with_ident(b, m, "as") {
435	            continue;
436	        }
437	        m += 2;
438	        while m < b.len() && b[m].is_ascii_whitespace() {
439	            m += 1;
440	        }
441	        let alias_start = m;
442	        while m < b.len() && is_ident_byte(b[m]) {
443	            m += 1;
444	        }
445	        if m > alias_start {
446	            if let Ok(alias) = std::str::from_utf8(&b[alias_start..m]) {
447	                aliases.push(alias.to_owned());
448	            }
449	        }
450	    }
451	    aliases
452	}
