462	/// What [`mask_trivia`] found while masking one file's source.
463	struct Masked {
464	    /// Source bytes with comments and literals blanked to spaces, so a scan
465	    /// over it sees only genuine code.
466	    buf: Vec<u8>,
467	    /// Byte ranges of genuine `//` line comments (including `///` and `//!`).
468	    /// [`collect_allow_marker_lines`] uses these to tell a real
469	    /// `// allow(tracing-target-syntax)` from that text inside a string.
470	    line_comments: Vec<(usize, usize)>,
471	    /// Byte ranges of string literals — plain, raw, byte and C strings —
472	    /// delimiters included. Char literals are excluded: they cannot hold a
473	    /// tracing target, and a lifetime (`'a`) is not a literal at all.
474	    ///
475	    /// `scan_targets` needs these because `buf` has blanked the very bytes a
476	    /// target string is made of. Reporting the span instead of un-blanking
477	    /// keeps one lexer authoritative over what counts as code — re-deriving
478	    /// literal boundaries in a second scanner is what the note at
479	    /// `collect_allow_marker_lines` warns against.
480	    string_literals: Vec<(usize, usize)>,
481	}
482	
483	/// Replace every byte inside a comment or literal with a space, preserving
484	/// length, byte offsets and newlines so offsets still map onto the original.
485	///
486	/// Also returns the byte ranges of every genuine **line comment** (`// …`
487	/// through end-of-line, which includes doc comments `///`/`//!` — they open
488	/// with the same two bytes this scan matches on). [`collect_allow_marker_lines`]
489	/// reuses these ranges to tell a real `// allow(tracing-target-syntax)`
490	/// comment apart from that same text merely appearing inside a string, a raw
491	/// string, or a block comment — all of which this function also blanks, but
492	/// does *not* record a range for, since only a line comment is a legitimate
493	/// home for the marker.
494	fn mask_trivia(src: &str) -> Masked {
495	    let b = src.as_bytes();
496	    let mut out = b.to_vec();
497	    let mut line_comments = Vec::new();
498	    let mut string_literals = Vec::new();
499	    let mut i = 0;
500	    while i < b.len() {
501	        match b[i] {
502	            b'/' if b.get(i + 1) == Some(&b'/') => {
503	                let start = i;
504	                while i < b.len() && b[i] != b'\n' {
505	                    i += 1;
506	                }
507	                blank(&mut out, start, i);
508	                line_comments.push((start, i));
509	            }
510	            b'/' if b.get(i + 1) == Some(&b'*') => {
511	                let start = i;
512	                let mut depth = 1usize;
513	                i += 2;
514	                while i < b.len() && depth > 0 {
515	                    if b[i] == b'/' && b.get(i + 1) == Some(&b'*') {
516	                        depth += 1;
517	                        i += 2;
518	                    } else if b[i] == b'*' && b.get(i + 1) == Some(&b'/') {
519	                        depth -= 1;
520	                        i += 2;
521	                    } else {
522	                        i += 1;
523	                    }
524	                }
525	                blank(&mut out, start, i);
526	            }
527	            b'r' | b'b' | b'c' => match raw_or_byte_string_end(b, i) {
528	                Some(end) => {
529	                    blank(&mut out, i, end);
530	                    string_literals.push((i, end));
531	                    i = end;
532	                }
533	                None => i += 1,
534	            },
535	            b'"' => {
536	                let start = i;
537	                i += 1;
538	                while i < b.len() {
539	                    if b[i] == b'\\' {
540	                        // Clamp: a trailing backslash at EOF (unterminated
541	                        // string) must not push `i` past `out.len()`, or the
542	                        // `blank` call below panics on an out-of-range slice.
543	                        i = (i + 2).min(b.len());
544	                    } else if b[i] == b'"' {
545	                        i += 1;
546	                        break;
547	                    } else {
548	                        i += 1;
549	                    }
550	                }
551	                blank(&mut out, start, i);
552	                string_literals.push((start, i));
553	            }
554	            b'\'' => match char_literal_end(b, i) {
555	                Some(end) => {
556	                    blank(&mut out, i, end);
557	                    i = end;
558	                }
559	                // A lifetime, not a literal — leave it alone.
560	                None => i += 1,
561	            },
562	            _ => i += 1,
563	        }
564	    }
565	    Masked {
566	        buf: out,
567	        line_comments,
568	        string_literals,
569	    }
570	}
