572	/// End (exclusive) of a raw or byte string starting at `i`, if one does.
573	fn raw_or_byte_string_end(b: &[u8], i: usize) -> Option<usize> {
574	    // `bar` must not read as a byte string starting at its `r`.
575	    if i > 0 && is_ident_byte(b[i - 1]) {
576	        return None;
577	    }
578	    let mut j = i;
579	    // `b` (byte string) and `c` (C string) may prefix either form: b"…" / br#"…"#
580	    // / c"…" / cr#"…"#. Without consuming the prefix, the `r` of `cr#` is read as
581	    // an identifier byte and the raw-string machinery never engages.
582	    if b[j] == b'b' || b[j] == b'c' {
583	        j += 1;
584	    }
585	    let raw = b.get(j) == Some(&b'r');
586	    if raw {
587	        j += 1;
588	        let hashes_start = j;
589	        while b.get(j) == Some(&b'#') {
590	            j += 1;
591	        }
592	        let hashes = j - hashes_start;
593	        if b.get(j) != Some(&b'"') {
594	            return None;
595	        }
596	        j += 1;
597	        while j < b.len() {
598	            if b[j] == b'"' {
599	                let mut k = j + 1;
600	                let mut seen = 0;
601	                while seen < hashes && b.get(k) == Some(&b'#') {
602	                    k += 1;
603	                    seen += 1;
604	                }
605	                if seen == hashes {
606	                    return Some(k);
607	                }
608	            }
609	            j += 1;
610	        }
611	        return Some(b.len());
612	    }
613	    if (b[i] != b'b' && b[i] != b'c') || b.get(j) != Some(&b'"') {
614	        return None;
615	    }
616	    j += 1;
617	    while j < b.len() {
618	        if b[j] == b'\\' {
619	            // Same clamp as the `b'"'` arm of `mask_trivia`: an escape at
620	            // EOF must not push `j` past `b.len()`.
621	            j = (j + 2).min(b.len());
622	        } else if b[j] == b'"' {
623	            return Some(j + 1);
624	        } else {
625	            j += 1;
626	        }
627	    }
628	    Some(b.len())
629	}
630	
631	/// End (exclusive) of a char literal starting at `i`, or `None` for a lifetime.
632	fn char_literal_end(b: &[u8], i: usize) -> Option<usize> {
633	    if b.get(i + 1) == Some(&b'\\') {
634	        // Start the scan for the closing `'` *after* the escaped character
635	        // (`i + 3`), not at it (`i + 2`). For `'\''` the byte at `i + 2` is
636	        // the escaped quote itself, not the closing delimiter — starting
637	        // there would stop one byte early and leave the real closing `'`
638	        // unmasked. Clamp so a trailing escape at EOF cannot push `j` past
639	        // `b.len()`.
640	        let mut j = (i + 3).min(b.len());
641	        while j < b.len() && b[j] != b'\'' {
642	            j += 1;
643	        }
644	        return if j < b.len() { Some(j + 1) } else { None };
645	    }
646	    let mut j = i + 1;
647	    if j >= b.len() {
648	        return None;
649	    }
650	    j += 1;
651	    // Consume UTF-8 continuation bytes of a multi-byte char.
652	    while j < b.len() && b[j] & 0b1100_0000 == 0b1000_0000 {
653	        j += 1;
654	    }
655	    if b.get(j) == Some(&b'\'') {
656	        Some(j + 1)
657	    } else {
658	        None
659	    }
660	}
