791	/// Find every `tracing` macro invocation in `src` and classify how each one
792	/// specifies (or fails to specify) its `target:` argument.
793	///
794	/// Recognises the same invocation shapes [`scan`]/[`try_scan`] do — final
795	/// path segment, any of the three delimiter kinds, `use`-aliased bare
796	/// forms — by sharing the same internal invocation walker, and is
797	/// comment/literal-blind for the same reason: it operates on the masked
798	/// buffer the trivia masker produces.
799	///
800	/// Unlike [`scan_targets`], this is macro-aware: a `target:` argument is
801	/// only classified when it is a top-level argument of a *recognised macro
802	/// invocation*, found by walking that invocation's own argument list — never
803	/// by a bare needle search over the whole file. An ordinary struct-literal
804	/// field named `target` (e.g. `Redirect { target: "/etc/passwd".into() }`)
805	/// is invisible to it, because no macro invocation surrounds that site at
806	/// all.
807	///
808	/// # Errors
809	///
810	/// Returns [`MismatchedDelimiter`] under the same unreachable-against-valid-Rust
811	/// condition [`try_scan`] documents.
812	pub fn scan_invocations(src: &str) -> Result<Vec<Invocation>, MismatchedDelimiter> {
813	    let masked = mask_trivia(src);
814	    let b = &masked.buf[..];
815	    let aliases = collect_macro_aliases(b);
816	    let mut invocations = Vec::new();
817	    walk_invocations(b, &aliases, |inv| {
818	        let target = classify_target_arg(b, inv.open, inv.closer, &masked.string_literals, src)?;
819	        invocations.push(Invocation {
820	            line: line_of(b, inv.name_start),
821	            macro_name: inv.name.to_owned(),
822	            target,
823	        });
824	        Ok(())
825	    })?;
826	    Ok(invocations)
827	}
828	
829	/// Classify one invocation's `target:` argument (see [`TargetArg`]),
830	/// looking only at its top-level arguments via [`for_each_top_level_arg`].
831	/// `string_literals` and `src` are [`Masked::string_literals`] and the
832	/// original (unmasked) source, needed to tell a literal value from a
833	/// non-literal one and to read the literal's content back out.
834	fn classify_target_arg(
835	    b: &[u8],
836	    open: usize,
837	    closer: u8,
838	    string_literals: &[(usize, usize)],
839	    src: &str,
840	) -> Result<TargetArg, MismatchedDelimiter> {
841	    let mut target = TargetArg::Absent;
842	    for_each_top_level_arg(b, open, closer, |k| {
843	        if !starts_with_ident(b, k, "target") {
844	            return;
845	        }
846	        let mut m = k + "target".len();
847	        while m < b.len() && b[m].is_ascii_whitespace() {
848	            m += 1;
849	        }
850	        // Only the `target:` keyword form actually sets the event's target;
851	        // `target = ...` compiles to an ordinary field (the SMA-543 defect)
852	        // and never reaches here as anything but `Absent`.
853	        if b.get(m) != Some(&b':') {
854	            return;
855	        }
856	        // Advance past real whitespace *and* comments (both blank to spaces
857	        // in `b`) to find where the value starts, but stop the instant a
858	        // position matches a known string-literal start — a literal's own
859	        // interior is also blanked to spaces in `b`, so a plain "skip
860	        // whitespace in `b`" loop would run straight through it and land on
861	        // whatever follows instead.
862	        let mut v = m + 1;
863	        while v < b.len()
864	            && b[v].is_ascii_whitespace()
865	            && !string_literals.iter().any(|&(start, _)| start == v)
866	        {
867	            v += 1;
868	        }
869	        target = match string_literals.iter().find(|&&(start, _)| start == v) {
870	            Some(&(start, end)) => {
871	                TargetArg::Literal(literal_content(&src[start..end]).unwrap_or("").to_owned())
872	            }
873	            None => TargetArg::NonLiteral,
874	        };
875	    })?;
876	    Ok(target)
877	}
