879	/// Lines (1-based) carrying a `#[tracing::instrument]` or bare
880	/// `#[instrument]` attribute.
881	///
882	/// Operates on the trivia masker's masked buffer, so an occurrence inside a
883	/// comment (e.g. a doc comment mentioning the attribute in prose) or a
884	/// string literal is invisible to it — matching
885	/// `crates/paigasus-helikon-macros/src/signature.rs:210`'s doc comment,
886	/// which names `#[tracing::instrument]` in a sentence and must not be
887	/// reported.
888	///
889	/// Recognised structurally, not by a bare text search: the `instrument`
890	/// identifier must be preceded (modulo whitespace, and modulo zero or more
891	/// `tracing::`/other path qualifiers immediately before it, including a
892	/// leading `::` root as in `#[::tracing::instrument]`) by an attribute's
893	/// opening `#[`. The attribute need not begin immediately there — being
894	/// anywhere inside the attribute's brackets counts, so
895	/// `#[cfg_attr(test, tracing::instrument)]` is also recognised. That keeps an
896	/// unrelated identifier or expression named `instrument` from being mistaken
897	/// for the attribute.
898	pub fn instrument_attribute_lines(src: &str) -> BTreeSet<usize> {
899	    let masked = mask_trivia(src);
900	    let b = &masked.buf[..];
901	    let mut lines = BTreeSet::new();
902	    let mut i = 0;
903	    while i < b.len() {
904	        if !is_ident_byte(b[i]) || (i > 0 && is_ident_byte(b[i - 1])) {
905	            i += 1;
906	            continue;
907	        }
908	        let start = i;
909	        while i < b.len() && is_ident_byte(b[i]) {
910	            i += 1;
911	        }
912	        if &b[start..i] == b"instrument" {
913	            let mut p = start;
914	            while p > 0 && b[p - 1].is_ascii_whitespace() {
915	                p -= 1;
916	            }
917	            // Skip zero or more optional qualifiers immediately before
918	            // `instrument`, e.g. the `tracing::` in `#[tracing::instrument]`,
919	            // looping so a leading `::` root (`#[::tracing::instrument]`) and
920	            // multi-segment paths are both fully stripped rather than just
921	            // the innermost segment.
922	            while p >= 2 && &b[p - 2..p] == b"::" {
923	                p -= 2;
924	                while p > 0 && is_ident_byte(b[p - 1]) {
925	                    p -= 1;
926	                }
927	                while p > 0 && b[p - 1].is_ascii_whitespace() {
928	                    p -= 1;
929	                }
930	            }
931	            if inside_attribute_brackets(b, p) {
932	                lines.insert(line_of(b, start));
933	            }
934	        }
935	    }
936	    lines
937	}
938	
939	/// Whether position `at` in the masked buffer `b` sits inside some
940	/// attribute's `#[ … ]` brackets, i.e. an unmatched `#[` is reachable by
941	/// walking backward from `at`.
942	///
943	/// Only `[`/`]` are tracked; `(`/`)` and `{`/`}` are transparent to the walk.
944	/// That is deliberate: `#[cfg_attr(test, tracing::instrument)]` nests
945	/// `instrument` inside `cfg_attr(...)`'s parens, one level below the
946	/// attribute's own brackets, and those parens must not stop the backward
947	/// search from reaching the enclosing `#[`.
948	fn inside_attribute_brackets(b: &[u8], at: usize) -> bool {
949	    let mut depth: i32 = 0;
950	    let mut k = at;
951	    while k > 0 {
952	        k -= 1;
953	        match b[k] {
954	            b']' => depth += 1,
955	            b'[' => {
956	                if depth == 0 {
957	                    return k > 0 && b[k - 1] == b'#';
958	                }
959	                depth -= 1;
960	            }
961	            _ => {}
962	        }
963	    }
964	    false
965	}
