1	//! Every `tracing` macro invocation under `crates/*/src` must carry an
2	//! explicit, well-shaped, correctly-attributed `target: "paigasus::…"`
3	//! literal, and no `#[tracing::instrument]` attribute may appear there
4	//! (SMA-568).
5	//!
6	//! Five properties are enforced per invocation:
7	//!
8	//! 1. A `target:` argument is present at all ([`TargetArg::Absent`] fails).
9	//! 2. It is a string literal, not a computed expression
10	//!    ([`TargetArg::NonLiteral`] fails) — a computed target satisfies
11	//!    coverage but cannot be shape-checked, which is exactly how an event
12	//!    could be routed out of the namespace invisibly.
13	//! 3. The literal is shaped `paigasus::<component>::<subsystem>`, both
14	//!    segments `[a-z0-9_]+` ([`is_well_shaped`]).
15	//! 4. The literal's `<component>` matches the component registered for the
16	//!    crate the file lives in ([`CRATE_COMPONENTS`]).
17	//! 5. No `#[tracing::instrument]`/`#[instrument]` attribute appears anywhere
18	//!    in the file — the scanner keys on `ident !` and cannot see an
19	//!    attribute, so an instrumented function would silently emit its span on
20	//!    its module path instead of a `paigasus::` target (SMA-568 D7).
21	//!
22	//! Assertion 3 deliberately does not check the component against the
23	//! mdBook — `tracing_target_docs.rs` already does that, and duplicating it
24	//! here would mean two tests reddening for one cause with two messages.
25	
26	use std::path::{Path, PathBuf};
27	
28	use paigasus_helikon_workspace_lints::{
29	    allow_marker_lines, instrument_attribute_lines, scan_invocations, TargetArg,
30	    ALLOW_MARKER_COVERAGE,
31	};
32	
33	/// Crate directory name (under `crates/`) to its registered
34	/// `paigasus::<component>`, for all 21 workspace members.
35	///
36	/// Ten of the twenty-one are reserved: they are name-claim stubs that emit no
37	/// tracing today, and per the design they must **not** appear in the
38	/// mdBook's component table (`tracing_target_docs.rs` asserts book and
39	/// source agree, and a row for an absent component fails it). They are still
40	/// listed here so a file that later appears under one of them resolves
41	/// instead of silently falling through the lookup, and so the
42	/// directory-existence assertion below covers all 21, not just the eleven
43	/// that are live.
44	///
45	/// Derivation rule for a future crate: strip `paigasus-helikon-`, then strip
46	/// a leading `providers-`, then replace `-` with `_`. The providers' bare
47	/// form (`openai`, not `providers_openai`) is a historical exception,
48	/// preserved because those names are the user-facing vendor names.
49	const CRATE_COMPONENTS: &[(&str, &str)] = &[
50	    ("paigasus-helikon", "facade"),
51	    ("paigasus-helikon-cli", "cli"),
52	    ("paigasus-helikon-core", "core"),
53	    ("paigasus-helikon-evals", "evals"),
54	    ("paigasus-helikon-macros", "macros"),
55	    ("paigasus-helikon-mcp", "mcp"),
56	    ("paigasus-helikon-providers-openai", "openai"),
57	    ("paigasus-helikon-providers-anthropic", "anthropic"),
58	    ("paigasus-helikon-providers-bedrock", "bedrock"),
59	    ("paigasus-helikon-providers-gemini", "gemini"),
60	    ("paigasus-helikon-providers-litellm", "litellm"),
61	    ("paigasus-helikon-runtime-tokio", "runtime_tokio"),
62	    ("paigasus-helikon-runtime-axum", "runtime_axum"),
63	    ("paigasus-helikon-runtime-actix", "runtime_actix"),
64	    ("paigasus-helikon-runtime-agentcore", "runtime_agentcore"),
65	    ("paigasus-helikon-runtime-temporal", "runtime_temporal"),
66	    ("paigasus-helikon-sessions-sqlite", "sessions_sqlite"),
67	    ("paigasus-helikon-sessions-postgres", "sessions_postgres"),
68	    ("paigasus-helikon-sessions-redis", "sessions_redis"),
69	    ("paigasus-helikon-sessions-testkit", "sessions_testkit"),
70	    ("paigasus-helikon-tools", "tools"),
71	];
