73	/// Repo root, derived from this crate's manifest directory rather than the
74	/// process CWD so it survives the member being moved.
75	fn repo_root() -> PathBuf {
76	    Path::new(env!("CARGO_MANIFEST_DIR"))
77	        .join("..")
78	        .join("..")
79	        .canonicalize()
80	        .expect("repo root must resolve from CARGO_MANIFEST_DIR")
81	}
82	
83	/// Collect `.rs` files under `dir`, skipping build output.
84	///
85	/// Uses [`std::fs::symlink_metadata`] rather than [`Path::is_dir`]: `is_dir`
86	/// follows symlinks, so a symlink pointing at an ancestor directory would
87	/// recurse this walk unboundedly.
88	fn collect_rs(dir: &Path, out: &mut Vec<PathBuf>) {
89	    let entries = std::fs::read_dir(dir).unwrap_or_else(|e| panic!("read_dir {dir:?}: {e}"));
90	    for entry in entries {
91	        let path = entry.expect("dir entry").path();
92	        let meta = std::fs::symlink_metadata(&path)
93	            .unwrap_or_else(|e| panic!("symlink_metadata {path:?}: {e}"));
94	        if meta.is_symlink() {
95	            continue;
96	        }
97	        let name = path
98	            .file_name()
99	            .and_then(|n| n.to_str())
100	            .unwrap_or_default();
101	        if meta.is_dir() {
102	            if name == "target" || name == ".git" {
103	                continue;
104	            }
105	            collect_rs(&path, out);
106	        } else if name.ends_with(".rs") {
107	            out.push(path);
108	        }
109	    }
110	}
111	
112	/// Whether `target` is shaped exactly `paigasus::<component>::<subsystem>`,
113	/// with both segments non-empty and drawn from `[a-z0-9_]+`.
114	///
115	/// Hand-rolled rather than a regex: this crate takes no dependencies. A
116	/// naive "split on `::` and take the first two segments" implementation
117	/// would wrongly accept `paigasus::core::agent::extra` (four segments); this
118	/// one rejects it, because after stripping the `paigasus::` prefix it splits
119	/// **exactly once** and requires the remainder to hold no further `::`.
120	fn is_well_shaped(target: &str) -> bool {
121	    let Some(rest) = target.strip_prefix("paigasus::") else {
122	        return false;
123	    };
124	    let Some((component, subsystem)) = rest.split_once("::") else {
125	        return false;
126	    };
127	    if subsystem.contains("::") {
128	        return false;
129	    }
130	    is_valid_segment(component) && is_valid_segment(subsystem)
131	}
132	
133	/// Whether `s` is a non-empty run of `[a-z0-9_]` bytes.
134	fn is_valid_segment(s: &str) -> bool {
135	    !s.is_empty()
136	        && s.chars()
137	            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_')
138	}
139	
140	/// `.rs` files under `crates_dir` whose path contains a `src` path
141	/// component — this excludes e.g.
142	/// `crates/paigasus-helikon-providers-anthropic/tests/live.rs`, the one
143	/// non-`src` `tracing` user under `crates/`.
144	fn collect_src_rs(crates_dir: &Path) -> Vec<PathBuf> {
145	    let mut all = Vec::new();
146	    collect_rs(crates_dir, &mut all);
147	    all.into_iter()
148	        .filter(|p| p.components().any(|c| c.as_os_str() == "src"))
149	        .collect()
150	}
151	
152	/// The crate directory name (e.g. `paigasus-helikon-core`) that `file`,
153	/// somewhere under `<crates_dir>/<crate-dir>/...`, belongs to.
154	fn crate_dir_of(file: &Path, crates_dir: &Path) -> String {
155	    let rel = file.strip_prefix(crates_dir).unwrap_or_else(|e| {
156	        panic!(
157	            "{} is not under {}: {e}",
158	            file.display(),
159	            crates_dir.display()
160	        )
161	    });
162	    rel.components()
163	        .next()
164	        .and_then(|c| c.as_os_str().to_str())
165	        .unwrap_or_else(|| panic!("{} has no leading path component", file.display()))
166	        .to_owned()
167	}
